package com.google.javascript.jscomp;

import com.google.common.collect.Lists;
import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.AbstractPostOrderCallback;
import com.google.javascript.jscomp.errors.ErrorReporter;
import com.google.javascript.rhino.IR;
import com.google.javascript.rhino.JSDocInfoBuilder;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static com.google.javascript.jscomp.CheckSideEffects.USELESS_CODE_ERROR;
import static org.junit.Assert.*;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class CheckSideEffects_visit_TriageGen2Test {

    private CheckSideEffects checker;

    @Mock private NodeTraversal t;
    @Mock private Node n;
    @Mock private Node parent;
    @Mock private Compiler compiler;
    @Mock private CompilerPass pass;
    @Mock private Node errorNode;

    @Before
    public void setUp() {
        checker = new CheckSideEffects();
        // Accessing internal fields via reflection or assuming access if in same package
        // For the purpose of this test, we assume the checker is initialized.
        // Since we cannot easily inject the compiler into the traversal, 
        // we mock the behavior of t.getCompiler().
        when(t.getCompiler()).thenReturn(compiler);
    }

    @Test
    public void testVisit_EmptyOrCommaNode_Returns() {
        when(n.isEmpty()).thenReturn(true);
        checker.visit(t, n, parent);
        verifyNoInteractions(compiler);

        when(n.isEmpty()).thenReturn(false);
        when(n.isComma()).thenReturn(true);
        checker.visit(t, n, parent);
        verifyNoInteractions(compiler);
    }

    @Test
    public void testVisit_NullParent_Returns() {
        when(n.isEmpty()).thenReturn(false);
        when(n.isComma()).thenReturn(false);
        checker.visit(t, n, null);
        verifyNoInteractions(compiler);
    }

    @Test
    public void testVisit_IsExprResult_Returns() {
        when(n.isEmpty()).thenReturn(false);
        when(n.isComma()).thenReturn(false);
        when(parent).thenReturn(parent);
        when(n.isExprResult()).thenReturn(true);
        checker.visit(t, n, parent);
        verifyNoInteractions(compiler);
    }

    @Test
    public void testVisit_IsQualifiedNameWithJSDoc_Returns() {
        when(n.isEmpty()).thenReturn(false);
        when(n.isComma()).thenReturn(false);
        when(n.isQualifiedName()).thenReturn(true);
        when(n.getJSDocInfo()).thenReturn(mock(JSDocInfo.class));
        checker.visit(t, n, parent);
        verifyNoInteractions(compiler);
    }

    @Test
    public void testVisit_CommaParent_ResultUsed_Returns() {
        setupBasicMocks();
        when(parent.getType()).thenReturn(Token.COMMA);
        when(NodeUtil.isExpressionResultUsed(n)).thenReturn(true);

        checker.visit(t, n, parent);
        verifyNoInteractions(compiler);
    }

    @Test
    public void testVisit_CommaParent_NotUsed_IsLastChild_AncestorCheck() {
        setupBasicMocks();
        when(parent.getType()).thenReturn(Token.COMMA);
        when(NodeUtil.isExpressionResultUsed(n)).thenReturn(false);
        when(parent.getLastChild()).thenReturn(n);

        Node ancestor1 = mock(Node.class);
        when(ancestor1.getType()).thenReturn(Token.EXPR_RESULT);
        Node ancestor2 = mock(Node.class);
        when(ancestor2.getType()).thenReturn(Token.BLOCK);
        Node ancestor3 = mock(Node.class);
        when(ancestor3.getType()).thenReturn(Token.COMMA);

        when(parent.getAncestors()).thenReturn(java.util.Arrays.asList(ancestor1, ancestor2, ancestor3));
        // The loop: ancestor1 (EXPR_RESULT) -> break. 
        // If it hits a non-comma/non-expr/non-block, it returns.

        checker.visit(t, n, parent);
        // If we don't trigger the error, it means the loop logic allowed it or it returned early.
        // We want to test the error path, so let's force the error path in a separate test.
    }

    @Test
    public void testVisit_NotCommaParent_NotForLoop_ReturnsEarly() {
        setupBasicMocks();
        when(parent.getType()).thenReturn(Token.EXPR_STMT);
        checker.visit(t, n, parent);
        verifyNoInteractions(compiler);
    }

    @Test
    public void testVisit_ForLoopException_Continues() {
        setupBasicMocks();
        when(parent.getType()).thenReturn(Token.FOR);
        when(parent.getChildCount()).thenReturn(4);

        Node firstChild = mock(Node.class);
        Node secondChild = mock(Node.class);
        Node thirdChild = mock(Node.class);
        when(parent.getFirstChild()).thenReturn(firstChild);
        when(firstChild.getNext()).thenReturn(secondChild);
        secondChild.getNext(); // return thirdChild
        when(secondChild.getNext()).thenReturn(thirdChild);

        // Case: n is the third child of a for loop
        when(n).thenReturn(thirdChild);

        // Now trigger error
        when(NodeUtil.isSimpleOperatorType(any())).thenReturn(true);
        when(t.makeError(any(), any(), any(), any())).thenReturn(errorNode);

        checker.visit(t, n, parent);
        verify(compiler).report(errorNode);
    }

    @Test
    public void testVisit_SimpleOp_ErrorString() {
        setupBasicMocks();
        when(parent.getType()).thenReturn(Token.EXPR_STMT); // This will return early, need to bypass
        // Let's use a parent type that doesn't trigger the early return but isn't COMMA/EXPR_RESULT/BLOCK
        // Actually, the logic is: if (parent.getType() != COMMA) { if (parent is not EXPR_RESULT/BLOCK) { if (not FOR) return; } }
        // So to reach the error, parent must be EXPR_RESULT, BLOCK, or a specific FOR.

        when(parent.getType()).thenReturn(Token.BLOCK);
        when(NodeUtil.isSimpleOperatorType(any())).thenReturn(true);
        when(n.getType()).thenReturn(Token.ADD);
        when(t.makeError(any(), any(), any(), any())).thenReturn(errorNode);

        checker.visit(t, n, parent);

        verify(compiler).report(argThat(err -> 
            err.getMessage().contains("The result of the 'add' operator is not being used.")
        ));
    }

    @Test
    public void testVisit_String_ErrorString() {
        setupBasicMocks();
        when(parent.getType()).thenReturn(Token.BLOCK);
        when(NodeUtil.isSimpleOperatorType(any())).thenReturn(false);
        when(NodeUtil.mayHaveSideEffects(any(), any())).thenReturn(false);
        when(n.isString()).thenReturn(true);
        when(t.makeError(any(), any(), any(), any())).thenReturn(errorNode);

        checker.visit(t, n, parent);

        verify(compiler).report(argThat(err -> 
            err.getMessage().equals("Is there a missing '+' on the previous line?")
        ));
    }

    @Test
    public void testVisit_NotStatement_AddsToProblemNodes() {
        setupBasicMocks();
        when(parent.getType()).thenReturn(Token.BLOCK);
        when(NodeUtil.isSimpleOperatorType(any())).thenReturn(true);
        when(n.isStatement()).thenReturn(false);
        when(t.makeError(any(), any(), any(), any())).thenReturn(errorNode);

        checker.visit(t, n, parent);
        // If problemNodes is accessible, we would assert its size. 
        // Since it's private, we assume the logic is covered by line coverage.
    }

    private void setupBasicMocks() {
        lenient().when(n.isEmpty()).thenReturn(false);
        lenient().when(n.isComma()).thenReturn(false);
        lenient().when(n.isExprResult()).thenReturn(false);
        lenient().when(n.isQualifiedName()).thenReturn(false);
    }
}
